            if c in " \t\r\n":
                self._advance()
            elif c == "#":
                while self.pos < len(self.text) and self.text[self.pos] != "\n":
                    self._advance()
            else:
                break

    def _skip_ws_inline(self):
        while self.pos < len(self.text) and self.text[self.pos] in " \t":
            self._advance()

    def _line_text(self, line_no: int) -> str:
        lines = self.text.split("\n")
        if 0 < line_no <= len(lines):
            return lines[line_no - 1]
        return ""

    def _err(self, message: str, line: int | None = None, col: int | None = None) -> TomlError:
        line = line if line is not None else self.line
        col = col if col is not None else self.col
        return TomlError(message, line, col, self._line_text(line))

    def parse(self):
        result = {}
        current = result
        current_path: list[str] = []
        while True:
            self._skip_ws_and_comments()
            if self.pos >= len(self.text):
                break
            c = self.text[self.pos]
            if c == "[":
                # Table header
                self._advance()
                parts = self._parse_key_parts()
                if self._peek() != "]":
                    raise self._err("expected ']'")
                self._advance()
                # Navigate
                current = result
                for p in parts:
                    if p not in current:
                        current[p] = {}
                    current = current[p]
                current_path = parts
                self._skip_ws_inline()
                if self.pos < len(self.text) and self.text[self.pos] == "#":
                    while self.pos < len(self.text) and self.text[self.pos] != "\n":
                        self._advance()
                if self.pos < len(self.text) and self.text[self.pos] == "\n":
                    self._advance()
            else:
                # Key-value
                key_line = self.line
                key_col = self.col
                parts = self._parse_key_parts()
                self._skip_ws_inline()
                if self._peek() != "=":
                    # key with no value
                    raise self._err("key with no value, expected `=`")
                self._advance()
                self._skip_ws_inline()
                val_line = self.line
                val_col = self.col
                value, val_type = self._parse_value()
                # Assign
                node = current
                for p in parts[:-1]:
                    if p not in node:
                        node[p] = {}
                    node = node[p]
                node[parts[-1]] = (value, val_type, val_line, val_col)
                self._skip_ws_inline()
                if self.pos < len(self.text) and self.text[self.pos] == "#":
                    while self.pos < len(self.text) and self.text[self.pos] != "\n":
                        self._advance()
                if self.pos < len(self.text) and self.text[self.pos] == "\n":
                    self._advance()
                elif self.pos >= len(self.text):
                    pass
        return result

    def _parse_key_parts(self) -> list[str]:
        parts = []
        while True:
            self._skip_ws_inline()
            if self._peek() == '"':
                parts.append(self._parse_string())
            else:
                start = self.pos
                while self.pos < len(self.text):
                    c = self.text[self.pos]
                    if c.isalnum() or c in "_-":
                        self._advance()
                    else:
                        break
                if self.pos == start:
                    raise self._err("expected key")
                parts.append(self.text[start:self.pos])
            self._skip_ws_inline()
            if self._peek() == ".":
                self._advance()
                continue
            break
        return parts

    def _parse_string(self) -> str:
        if self._peek() != '"':
            raise self._err("expected string")
        self._advance()
        result = []
        while self.pos < len(self.text):
            c = self.text[self.pos]
            if c == '"':
                self._advance()
                return "".join(result)
            if c == "\\":
                self._advance()
                n = self._peek()
                mapping = {"n": "\n", "t": "\t", "r": "\r", "\\": "\\", '"': '"', "0": "\0"}
                if n in mapping:
                    result.append(mapping[n])
                    self._advance()
                else:
                    result.append(n)
                    self._advance()
            elif c == "\n":
                raise self._err("unterminated string")
            else:
                result.append(c)
                self._advance()
        raise self._err("unterminated string")

    def _parse_value(self):
        c = self._peek()
        line = self.line
        col = self.col
        if c == '"':
            return self._parse_string(), "string"
        if c.isdigit() or c in "+-":
            start = self.pos
            self._advance()
            while self.pos < len(self.text):
                ch = self.text[self.pos]
                if ch.isdigit() or ch in "_.eE+-":
                    self._advance()
                else:
                    break
            raw = self.text[start:self.pos]
            # Clean underscores
            clean = raw.replace("_", "")
            try:
                if "." in clean or "e" in clean or "E" in clean:
                    return float(clean), "float"
                return int(clean), "int"
            except ValueError:
                raise self._err(f"invalid number: {raw}", line, col)
        if self.text.startswith("true", self.pos):
            self._advance(4)
            return True, "bool"
        if self.text.startswith("false", self.pos):
            self._advance(5)
            return False, "bool"
        raise self._err("expected value", line, col)


def parse(text: str) -> dict:
    return _Parser(text).parse()
